import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');

// Module-level font loading guaranteed to be ready before frame 0
const { fontFamily: oswaldFamily } = loadOswald();

// --- SCHEMA DEFINITION ---


export type BlackjackFlightProps = Record<string, any>;

// --- HELPER COMPONENTS (Inline SVGs) ---
