const PlayingCard: React.FC<{
  value: string;
  suit: "spade" | "heart";
  width: number;
  height: number;
  rotation: number;
  zIndex: number;
  offsetX: number;
  offsetY: number;
}> = ({ value, suit, width, height, rotation, zIndex, offsetX, offsetY }) => {
  const isRed = suit === "heart";
  const cardColor = isRed ? "#e63946" : "#1a1a1a";
  const Icon = suit === "heart" ? HeartIcon : SpadeIcon;

  return (
    <div
      style={{
        position: "absolute",
        width,
        height,
        backgroundColor: "#ffffff",
        borderRadius: width * 0.08,
        boxShadow: `-${width * 0.05}px ${width * 0.05}px ${width * 0.15}px rgba(0,0,0,0.6)`,
        display: "flex",
        flexDirection: "column",
        padding: width * 0.08,
        boxSizing: "border-box",
        transform: `translate(-50%, -50%) translate(${offsetX}px, ${offsetY}px) rotate(${rotation}deg)`,
        zIndex,
        border: `${width * 0.02}px solid #e2e8f0`,
      }}
    >
      <div
        style={{
          fontFamily: oswaldFamily,
          fontSize: width * 0.3,
          fontWeight: 700,
          color: cardColor,
          lineHeight: 1,
        }}
      >
        {value}
      </div>
      <div style={{ marginTop: -width * 0.03 }}>
        <Icon size={width * 0.25} color={cardColor} />
      </div>
      {/* Center graphic */}
      <div
        style={{
          flex: 1,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <Icon size={width * 0.45} color={cardColor} />
      </div>
    </div>
  );
};

// --- MAIN COMPONENT ---
const BlackjackFlightAnimation: React.FC<BlackjackFlightProps> = ({
  backgroundColor = "#0c4a28", // Casino Felt Green Default
  transparentBackground = false,
  durationInSeconds = 5,
  title = "BLACKJACK",
  subtitle = "FOR FREE",
  highlightText = "FLIGHT CREDITS",
  primaryTextColor = "#ffffff",
  accentColor = "#ffd700", // Luxurious Gold Default
  highlightColor = "#e63946", // Casino Red Default
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- TIMING CONFIGURATION ---
  const tTitleIn = spring({ frame: frame - 10, fps, config: { damping: 14 } });
  const tSubtitleIn = spring({ frame: frame - 25, fps, config: { damping: 14 } });
  const tHighlightIn = spring({ frame: frame - 40, fps, config: { damping: 14 } });

  // Flight sequence starts slightly after text, takes a few seconds
  const flightStartFrame = 50;
  const flightDuration = 90;
  const tFlight = interpolate(
    frame,
    [flightStartFrame, flightStartFrame + flightDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // --- TRAJECTORY MATH (De Casteljau for Quadratic Bezier) ---
  const P0 = { x: width * 0.4, y: height * 0.85 };
  const P1 = { x: width * 0.7, y: height * 1.1 }; 
  const P2 = { x: width * 0.95, y: height * 0.2 };

  const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

  const A = { x: lerp(P0.x, P1.x, tFlight), y: lerp(P0.y, P1.y, tFlight) };
  const B = { x: lerp(P1.x, P2.x, tFlight), y: lerp(P1.y, P2.y, tFlight) };
  const Tip = { x: lerp(A.x, B.x, tFlight), y: lerp(A.y, B.y, tFlight) };

  // Tangent angle at the tip (rider orientation)
  const angleRad = Math.atan2(Tip.y - A.y, Tip.x - A.x);
  const angleDeg = angleRad * (180 / Math.PI);

  // Partial path for the trail drawing dynamically with the rider
  const partialTrailPath = `M ${P0.x} ${P0.y} Q ${A.x} ${A.y} ${Tip.x} ${Tip.y}`;

  // --- MORPH LOGIC ---
  const flipStart = 0.45;
  const flipEnd = 0.55;
  const cardScaleX = interpolate(tFlight, [flipStart, flipStart + 0.05], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const planeScaleX = interpolate(tFlight, [flipEnd - 0.05, flipEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Fade cards slightly as they fly before flipping
  const cardOpacity = interpolate(tFlight, [0, flipStart], [1, 0.8], {
    extrapolateRight: "clamp",
  });

  // Entrance pop for the cards at P0 before they take off
  const tCardsEnter = spring({
    frame: frame - 30,
    fps,
    config: { damping: 12, mass: 0.8 },
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* --- CASINO BACKGROUND WATERMARKS --- */}
      {!transparentBackground && (
        <div style={{ position: "absolute", inset: 0, opacity: 0.04, pointerEvents: "none" }}>
          <div style={{ position: "absolute", top: "15%", left: "15%", transform: "rotate(-12deg)" }}><SpadeIcon size={140 * s} color="#ffffff" /></div>
          <div style={{ position: "absolute", top: "20%", right: "20%", transform: "rotate(15deg)" }}><HeartIcon size={160 * s} color="#ffffff" /></div>
          <div style={{ position: "absolute", bottom: "25%", left: "25%", transform: "rotate(8deg)" }}><DiamondIcon size={130 * s} color="#ffffff" /></div>
          <div style={{ position: "absolute", bottom: "15%", right: "15%", transform: "rotate(-20deg)" }}><ClubIcon size={150 * s} color="#ffffff" /></div>
        </div>
      )}

      {/* --- CASINO TABLE GOLD BORDER --- */}
      <div
        style={{
          position: "absolute",
          inset: 24 * s,
          border: `${6 * s}px double ${accentColor}`,
          borderRadius: 16 * s,
          pointerEvents: "none",
          opacity: 0.7,
          boxShadow: `inset 0 0 ${40 * s}px rgba(0, 0, 0, 0.6)`,
        }}
      />

      {/* --- TRAIL SVGS (Drawn progressively) --- */}
      {tFlight > 0 && (
        <svg
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            pointerEvents: "none",
          }}
        >
          {/* Outer glow / shadow trail */}
          <path
            d={partialTrailPath}
            fill="none"
            stroke="#543c0c"
            strokeWidth={120 * s}
            strokeLinecap="round"
            style={{ transition: "none", opacity: 0.5 }}
          />
          {/* Inner accent trail */}
          <path
            d={partialTrailPath}
            fill="none"
            stroke={highlightColor}
            strokeWidth={80 * s}
            strokeLinecap="round"
            style={{ transition: "none", opacity: 0.8 }}
          />
          {/* Core bright trail */}
          <path
            d={partialTrailPath}
            fill="none"
            stroke="#ffffff"
            strokeWidth={40 * s}
            strokeLinecap="round"
            style={{ transition: "none" }}
          />
        </svg>
      )}

      {/* --- ANIMATED RIDER (Cards morphing into Plane) --- */}
      {tCardsEnter > 0 && (
        <div
          style={{
            position: "absolute",
            left: tFlight > 0 ? Tip.x : P0.x,
            top: tFlight > 0 ? Tip.y : P0.y,
            width: 0,
            height: 0,
            transform: `scale(${tCardsEnter}) rotate(${tFlight > 0 ? angleDeg + 30 : -15}deg)`,
            transition: "none",
          }}
        >
          {/* Cards Wrapper - Disappears halfway through flight */}
          {tFlight < flipEnd && (
            <div
              style={{
                position: "absolute",
                transform: `scaleX(${cardScaleX})`,
                opacity: cardOpacity,
                transition: "none",
              }}
            >
              <PlayingCard
                value="A"
                suit="heart"
                width={200 * s}
                height={280 * s}
                rotation={-15}
                zIndex={1}
                offsetX={-50 * s}
                offsetY={0}
              />
              <PlayingCard
                value="J"
                suit="spade"
                width={200 * s}
                height={280 * s}
                rotation={5}
                zIndex={2}
                offsetX={30 * s}
                offsetY={-10 * s}
              />
            </div>
          )}

          {/* Plane Wrapper - Appears halfway through flight */}
          {tFlight > flipStart && (
            <div
              style={{
                position: "absolute",
                transform: `translate(-50%, -50%) scaleX(${planeScaleX}) rotate(45deg)`,
                opacity: planeScaleX,
                transition: "none",
              }}
            >
              {/* Plane shadow/offset */}
              <div style={{ position: "absolute", top: 10 * s, left: -10 * s, filter: 'brightness(0.2)' }}>
                  <PlaneIcon size={300 * s} color="#000000" />
              </div>
              <PlaneIcon size={300 * s} color="#ffffff" />
            </div>
          )}
        </div>
      )}

      {/* --- TYPOGRAPHY BLOCK (Left Side) --- */}
      <div
        style={{
          position: "absolute",
          left: width * 0.08,
          top: 0,
          width: width * 0.5,
          height: "100%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          fontFamily: oswaldFamily,
        }}
      >
        {/* Top Accent Icon */}
        <div
          style={{
            transform: `translateY(${interpolate(tTitleIn, [0, 1], [50 * s, 0])}) scale(${tTitleIn})`,
            opacity: tTitleIn,
            marginBottom: 20 * s,
          }}
        >
          <SpadeIcon size={80 * s} color={accentColor} />
        </div>

        {/* Main Title */}
        <div
          style={{
            fontSize: 220 * s,
            fontWeight: 700,
            color: primaryTextColor,
            lineHeight: 0.9,
            letterSpacing: 2 * s,
            transform: `translateY(${interpolate(tTitleIn, [0, 1], [50 * s, 0])})`,
            opacity: tTitleIn,
            whiteSpace: "nowrap",
            textShadow: `0 ${8 * s}px ${16 * s}px rgba(0, 0, 0, 0.5)`,
          }}
        >
          {title.toUpperCase()}
        </div>

        {/* Subtitle with flanking lines and gold beads */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            width: "80%",
            marginTop: 10 * s,
            marginBottom: 10 * s,
            opacity: tSubtitleIn,
            transform: `scale(${interpolate(tSubtitleIn, [0, 1], [0.9, 1])})`,
          }}
        >
          <div style={{ flex: 1, height: 4 * s, backgroundColor: accentColor, position: "relative" }}>
            <div style={{ position: "absolute", right: 0, top: -2 * s, width: 8 * s, height: 8 * s, borderRadius: "50%", backgroundColor: accentColor }} />
          </div>
          <div
            style={{
              fontSize: 60 * s,
              fontWeight: 700,
              color: accentColor,
              margin: `0 ${30 * s}px`,
              letterSpacing: 4 * s,
              whiteSpace: "nowrap",
              textShadow: `0 ${4 * s}px ${8 * s}px rgba(0, 0, 0, 0.4)`,
            }}
          >
            {subtitle.toUpperCase()}
          </div>
          <div style={{ flex: 1, height: 4 * s, backgroundColor: accentColor, position: "relative" }}>
            <div style={{ position: "absolute", left: 0, top: -2 * s, width: 8 * s, height: 8 * s, borderRadius: "50%", backgroundColor: accentColor }} />
          </div>
        </div>

        {/* Highlight Text */}
        <div
          style={{
            fontSize: 140 * s,
            fontWeight: 700,
            color: highlightColor,
            lineHeight: 1,
            letterSpacing: 1 * s,
            transform: `translateY(${interpolate(tHighlightIn, [0, 1], [50 * s, 0])})`,
            opacity: tHighlightIn,
            whiteSpace: "nowrap",
            textShadow: `0 ${6 * s}px ${12 * s}px rgba(0, 0, 0, 0.4)`,
          }}
        >
          {highlightText.toUpperCase()}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default BlackjackFlightAnimation;